{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/zone-table.json
    Delivery zones and their prices as a table or as cards: the zone and its areas, the price, the order that ships free, the minimum order, the time and an express badge. Axes: layout (table, cards), tone, density.
    Props (p): id, title, lead, zones, labels, layout, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_zones = ($p['zones'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_18}
  {if ui_t(ui_eq($v_layout, 'table'))}
    {=ui_include('blocks/zone-rows.latte', ['p' => ['zones' => $v_zones, 'labels' => $v_labels]])|noescape}
  {else}
    {capture $c_17}
      {foreach ui_l($v_zones) as $v_z}
        {capture $c_16}
          {capture $c_3}
            {capture $c_1}
              {=ui_text(ui_get($v_z, ['name']))}
            {/capture}
            {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
            {capture $c_2}
              {=ui_text(ui_get($v_z, ['area']))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
          {/capture}
          {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_3])|noescape}
          {capture $c_4}
            {=ui_text(ui_money(ui_get($v_z, ['price']), ui_get($v_z, ['currency'])))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => '3xl', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
          {capture $c_14}
            {capture $c_7}
              {capture $c_5}
                {=ui_text(ui_get($v_labels, ['freeFrom']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
              {capture $c_6}
                {=ui_text(ui_money(ui_get($v_z, ['freeFrom']), ui_get($v_z, ['currency'])))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'font-medium'], 'children' => $c_6])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center justify-between gap-4 text-sm'], 'children' => $c_7])|noescape}
            {capture $c_10}
              {capture $c_8}
                {=ui_text(ui_get($v_labels, ['minOrder']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'text-muted-foreground'], 'children' => $c_8])|noescape}
              {capture $c_9}
                {=ui_text(ui_money(ui_get($v_z, ['minOrder']), ui_get($v_z, ['currency'])))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'font-medium'], 'children' => $c_9])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center justify-between gap-4 text-sm'], 'children' => $c_10])|noescape}
            {capture $c_13}
              {capture $c_11}
                {=ui_text(ui_get($v_labels, ['time']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'text-muted-foreground'], 'children' => $c_11])|noescape}
              {capture $c_12}
                {=ui_text(ui_get($v_z, ['time']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'font-medium'], 'children' => $c_12])|noescape}
            {/capture}
            {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-center justify-between gap-4 text-sm'], 'children' => $c_13])|noescape}
          {/capture}
          {=ui_include('ui/list/list.latte', ['p' => ['Tag' => 'ul', 'Class' => 'flex flex-col gap-2 border-t border-border pt-4'], 'children' => $c_14])|noescape}
          {if ui_t(ui_get($v_z, ['express']))}
            {capture $c_15}
              {=ui_text(ui_get($v_z, ['express']))}
            {/capture}
            {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'default', 'Class' => 'w-fit'], 'children' => $c_15])|noescape}
          {/if}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-6', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_16])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-3', 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_17])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_18])|noescape}
